import {profileMetrics,recentSolvesMarkup} from './profile-extras.js?v=profile-compact-1&rewards=4&streak-correction=1';
import {earnedStreakBadgesMarkup} from './streak-awards.js?v=lifetime-1&badge-7-compact=8';
import {escapeHtml as h} from './community-model.js';
import {rankRibbonBadge} from './rewards.js?v=ribbon-1';
import {findCompany} from './companies.js?v=social-1';
import {yearCalendar,calendarYears,calendarMonthsMarkup} from './profile-calendar.js?v=calendar-clean-1';
import {languageNames,profileDetails} from './profile-fields.js?v=profile-github-1';
export const publicProfileHref=p=>'./community.html#user/'+encodeURIComponent(p.username||p.public_id||'');
export function profileAvatar(p,large=false){return p?.avatar_url&&/^https:\/\//.test(p.avatar_url)?'<img class="avatar '+(large?'large':'')+'" src="'+h(p.avatar_url)+'" alt="" referrerpolicy="no-referrer" loading="lazy">':'<span class="avatar '+(large?'large':'')+'">'+h((p?.display_name||p?.username||'?').trim().charAt(0).toUpperCase())+'</span>';}
export function profileIcon(p){return '<a class="user-profile-icon" href="'+publicProfileHref(p)+'" aria-label="View '+h(p.display_name||p.username||'learner')+' profile" title="View ProSolver profile"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><circle cx="12" cy="8" r="3"/><path d="M5 21v-2a7 7 0 0 1 14 0v2M18 3h4v4M22 3l-5 5"/></svg></a>';}
function organization(p){let d;try{d=profileDetails(p);}catch{return '';}if(!d.organization_name)return '';const c=findCompany(d.organization_name),icon=c?'<img src="'+c.file+'" alt="" loading="lazy">':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="m3 8 9-5 9 5M4 9h16M5 10v9m5-9v9m4-9v9m5-9v9M3 21h18"/></svg>',label='<span class="organization-icon">'+icon+'</span><span>'+h(d.organization_name)+'</span>';return d.organization_url?'<a class="profile-organization" href="'+h(d.organization_url)+'" target="_blank" rel="noopener noreferrer" title="'+h(d.organization_type)+' · provided by this user">'+label+'</a>':'<span class="profile-organization" title="'+h(d.organization_type)+' · provided by this user">'+label+'</span>';}
function socialLinks(p){
 let d;try{d=profileDetails(p);}catch{return '';}
 const linkedin=d.linkedin_url?'<a class="profile-linkedin" href="'+h(d.linkedin_url)+'" target="_blank" rel="noopener noreferrer" aria-label="Open LinkedIn profile" title="LinkedIn"><img src="./assets/companies/linkedin.svg" alt=""></a>':'';
 const github=d.github_url?'<a class="profile-github" href="'+h(d.github_url)+'" target="_blank" rel="noopener noreferrer" aria-label="Open GitHub profile" title="GitHub"><img src="./assets/companies/github.svg" alt=""></a>':'';
 return linkedin+github;
}
export function profileMarkup(r,{catalogCount=0,catalog=[],admin=false,canFollow=true}={}){
 const p=r.profile,rank=Number(r.ranking?.rank)||0,medal=({1:'gold',2:'silver',3:'bronze'})[rank]||'',calendar=yearCalendar(r.stats.days,r.stats.serverDay),years=calendarYears(r.stats.days,r.stats.serverDay),skills=r.insights?.skills||[],languages=(r.insights?.languages||[]).filter(x=>languageNames[x.language]).sort((a,b)=>(Number(b.solved)||0)-(Number(a.solved)||0)),points=Number(r.ranking?.points||0),streak=Number(r.stats.streak)||0;
 return '<section class="profile-main-card profile-unboxed"><div class="profile-overview"><div class="profile-person"><div class="profile-hero"><span class="profile-avatar-frame">'+profileAvatar(p,true)+rankRibbonBadge(rank)+'</span><div class="profile-identity"><span class="eyebrow">PROFILE</span><h2 class="profile-title '+(medal?'medal-'+medal:'')+'"><span class="rank-name-text">'+h(p.display_name)+'</span><span class="profile-inline-rank">'+(rank?'#'+rank+' global':'Unranked')+'</span>'+(p.is_admin?'<span class="admin-badge">Admin</span>':'')+'</h2><div class="profile-username-line"><span>@'+h(p.username)+(p.discoverable?'':' · private profile')+'</span><span id="profilePresenceStatus" class="presence" role="status"></span>'+socialLinks(p)+'</div><div class="profile-connections"><button data-connections="followers"><strong>'+Number(r.followers||0)+'</strong> followers</button><span>·</span><button data-connections="following"><strong>'+Number(r.following||0)+'</strong> following</button></div>'+organization(p)+'</div><div class="profile-actions">'+(r.isOwn?'<a class="button secondary" href="#edit">Edit profile</a>':!canFollow?'<a class="button secondary" href="#edit">Create a discoverable profile to follow</a>':'<button id="followBtn" class="button primary">'+(r.isFollowing?'Following ✓':'Follow +')+'</button>'+(r.isFollowing?'<button id="messageFriend" class="button secondary">Message</button>':''))+'</div></div>'+(p.bio?'<p class="profile-bio">'+h(p.bio)+'</p>':'')+'</div>'+profileMetrics(r.stats,points,catalogCount)+'</div>'+earnedStreakBadgesMarkup(r.stats.days,r.stats.serverDay)+'<section class="profile-calendar-section">'+'<div class="calendar-heading"><div><h3>Solving calendar</h3><span>Accepted solve days · UTC</span></div><label class="calendar-year-picker" for="profileCalendarYear"><span>Year</span><select id="profileCalendarYear" aria-label="Choose solving calendar year">'+years.map(year=>'<option value="'+year+'"'+(year===calendar.year?' selected':'')+'>'+year+'</option>').join('')+'</select></label></div><div class="activity-scroll month-calendar-scroll" tabindex="0" aria-label="Solving calendar year view"><div class="calendar-heatmap-layout"><div class="calendar-weekdays" aria-hidden="true"><span></span><span>Mon</span><span></span><span>Wed</span><span></span><span>Fri</span><span></span></div><div id="profileCalendarMonths" class="month-calendar" role="group" aria-label="Accepted solve days in '+calendar.year+'">'+calendarMonthsMarkup(calendar)+'</div></div></div><div class="activity-legend"><span id="profileCalendarRange">'+calendar.start+' → '+calendar.end+'</span><div class="calendar-legend-right"><span id="profileCalendarActivity">'+calendar.activeCount+' '+(calendar.activeCount===1?'solve day':'solve days')+'</span><span class="calendar-key" aria-label="Calendar key: muted square means no solve, green means accepted solve"><span>No solve</span><i class="calendar-key-idle" aria-hidden="true"></i><i class="calendar-key-active" aria-hidden="true"></i><span>Accepted</span></span></div></div><p class="calendar-note">Streaks count consecutive UTC days with accepted solves.</p>'+'</section>'+recentSolvesMarkup(r.insights?.recentSolves||[],catalog)+'<div class="profile-expertise"><section><h3>Skills practiced</h3><div class="profile-skill-list">'+(skills.length?skills.map(s=>'<span class="skill-chip">'+h(s.name)+'<small>'+Number(s.solved)+' solved</small></span>').join(''):'<p class="muted">Skills appear as problems are solved.</p>')+'</div></section><section><h3>Languages used</h3><div class="profile-language-list">'+(languages.length?languages.map(l=>'<span class="language-chip" data-language="'+h(l.language)+'">'+languageNames[l.language]+'<small>'+Number(l.solved)+' solved</small></span>').join(''):'<p class="muted">Languages appear after accepted submissions.</p>')+'</div></section></div>'+(r.isOwn&&admin?'<a class="button secondary manage-creators" href="#roles">Manage creators ↗</a>':'')+'</section>';
}
